return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'so_SO','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T12:04:52+00:00','po-revision-date'=>'2026-09-26T12:04:52+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','The foundation release of the rebuilt Tranzly: a list of your site\'s languages, a language switcher block, and the language API other plugins read.'=>'Nuqulkii asaasiga ahaa ee Tranzly ee dib loo dhisay: liiska luqadaha mareegtaada, baloogga beddelaha luqadda, iyo API-ga luqadda ee ay akhriyaan qalabka kale ee lagu daro.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Bixiyeyaasha AI','The makers of ChatGPT. A good all-rounder.'=>'Sameeyayaasha ChatGPT. Qalab guud oo wanaagsan.','The makers of Claude. Strong at writing and careful reasoning.'=>'Sameeyeyaasha Claude. Ku xooggan qorista iyo sababaynta taxaddarka leh.','Google\'s Gemini models. Fast and inexpensive.'=>'Moodellada Gemini ee Google. Degdeg ah oo jaban.','A European AI company with fast, inexpensive models.'=>'Shirkad AI oo Yurub ah oo leh moodallo degdeg ah oo jaban.','Low-cost models that are good at writing and code.'=>'Qaabab jaban oo ku wanaagsan qorista iyo koodhka.','One key for models from many different providers.'=>'Hal furaha oo loogu talagalay moodooyinka ka kala yimid bixiyeyaal badan.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Adeeg kasta oo u shaqeeya sida OpenAI\'s API, oo ay ku jirto nooc ka shaqaynaya kombuyuutarkaaga ama adeerahaaga.','General (used when nothing more specific is set)'=>'Guud ahaan (la isticmaalo marka aan wax gaar ah la cayimin)','Writing and rewriting'=>'Qorista iyo dib-u-qorista','Translation'=>'Turjumaad','Code and CSS'=>'Koodhka iyo CSS','Sorry, you are not allowed to access this page.'=>'Waan ka xunnahay, looma oggola inaad gasho boggan.','These settings are shared by every plugin that uses them: %s.'=>'Goobahaan waxaa wadaagaya dhammaan qalabka (plugin) ee isticmaala: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Furayaashaada waxaa lagu kaydiyay xog-ururinta boggan waxaana loo diraa oo keliya bixiyaha aad dooratay — weligood annogu nooma soo diraan.','Step 1 of 2: choose an AI provider'=>'Tallaabada 1 ee 2: dooro bixiye AI ah','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Waxaad keeneysaa furahaaga, markaas waxaad si toos ah uga bixisaa bixiyaha wixii aad isticmaasho. Ma hubtid? Mid kasta oo ka mid ah kuwan ayaa si fiican u shaqeeya; waxaad ku dari kartaa kuwo kale hadhow.','Next'=>'Xiga','Step 2 of 2: connect %s'=>'Tallaabada 2 ee 2: ku xidh %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Geli cinwaanka adeeggaaga OpenAI-compatible, oo ku dhammaanaya /v1. Muhiimad lama siiyo furaha illaa adeeggu uu mid dalbado mooyaane.','Open %s and sign in (or create a free account).'=>'Furo %s oo gala (ama samee akoon bilaash ah).','the %s API keys page'=>'bogga furayaasha API ee %s','Create a new key and copy it.'=>'Samee furaha cusub oo koobi garee.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Halkan ku dheji oo riix "Keydi oo tijaabi". Waxaan direynaa hal codsi yar si aan u hubino in uu shaqeynayo.','Most providers need a little credit on the account before a key works: %s.'=>'Int aksaar ah waxay u baahan yihiin xoogaa deyn ah oo ku jirta akoonka ka hor intaysan furuhu shaqayn: %s.','add credit'=>'ku dar deyn','← Choose a different provider'=>'← Dooro bixiye kale','Address'=>'Cinwaanka','Saved key ends in …%s — paste a new one to replace it'=>'Furaha la kaydiyay wuxuu ku dhammaanayaa …%s — dhejiso mid cusub si aad u beddesho','Key (optional)'=>'Furaha (ikhtiyaari)','API key'=>'Furaha API','Save and test'=>'Kaydi oo tijaabi','Providers'=>'Bixiyeyaasha','Provider'=>'Bixiyaha','Status'=>'Xaaladda','Key'=>'Furaha','Get a key'=>'Key ka hel','Test'=>'Tijaabi','Remove'=>'Ka saar','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Waxaa kaydiyay nooc cusub oo ah plugin: cusboonaysii plugin-kan, ama geli furaha mar labaad.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Furaha la kaydiyay mar dambe lama furi karo (furayaasha amniga ee boggu waa is beddeleen). Dib u geli.','Not connected'=>'Lama xiriirin','Connected — last test passed %s'=>'Ku xiran — imtixaankii ugu dambeeyay wuu guuleystay %s','Last test failed: %s'=>'Imtixaankii ugu dambeeyay wuu guuldarraystay: %s','Connected — not tested yet'=>'Ku xidhan — wali lama tijaabin','Which model to use'=>'Noocyadee la isticmaalayaa','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ waxay calaamadeysaa taladeena hawshaas. Liiska waxaa ku jira dhammaan noocyada uu furahaagu isticmaali karo, kuwaas oo si toos ah looga aqriyay bixiyaha.','— Recommended for the provider —'=>'— Lagetaliyey bixiyaha —','Save models'=>'Kaydi moodellada','Refresh the model lists from the providers'=>'Ka cusbooneysii liiska moodelada bixiyeyaasha','best quality'=>'tayada ugu fiican','lowest cost'=>'kharashka ugu hooseeya','fastest'=>'ugu dhaqso badan','Add a model yourself'=>'Naftaada ku dar qaab','A model came out today? Paste its exact name to use it straight away.'=>'Qaab cusub ayaa soo baxay maanta? Ku dheji magaciisa saxda ah si aad si toos ah u isticmaasho.','Model name'=>'Magaca qaabka','Add model'=>'Ku dar qaabka','Recommended models list'=>'Liiska moodellada lagu talinayo','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Liiska moodeellada lagu talinayo lama xaqiijin karo, markaa lama tusayo wax talo soo jeedin ah. Dib ugu rakib furaha (plugin), ama daar cusboonaysiinta maalinlaha ah ee hoose.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Liiska la isticmaalayo waxaa la daabacay %s. Cusboonaysiin kasta oo plugin ah waxay keentaa mid cusub.','Also check Zinn Digital® once a day for an updated list.'=>'Sidoo kale hubi Zinn Digital® hal mar maalintii si aad u hesho liis cusboonaysiiyey.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Kaliya codsi dejisan oo fudud ayaa la dirayaa: ma jiro fure, ma jiro ciwaan degel ah, wax walba oo ku saabsan nuxurkaaga ma jiraan. Liiska waa la saxiixay, liiska ku guuldareysta hubinta saxiixana waa la iska indhatirayaa.','Last checked %1$s: %2$s.'=>'Markii ugu dambeysay ee la hubiyay %1$s: %2$s.','Save, and check now if turned on'=>'Keydi, kadibna hubi hadda haddii la shiday','a newer list was installed'=>'liis ka cusub ayaa la rakibay','already up to date'=>'hore ula jaanqaaday','the download failed the signature check and was ignored'=>'soo dejinta ayaa ku guuldareysatay hubinta saxiixa waana la iska indhatiray','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® lama gaari karin; liiska hadda jira waa in la isticmaalo','turned off'=>'damacsan','Open'=>'Furo','Check their status page'=>'Hubi boggooda xaaladda','Open your billing page'=>'Fur boggaaga biilasha','Open your API keys page'=>'Fur bogtaada API keys','Open the AI settings'=>'Fur goobaha AI','Sorry, you are not allowed to do that.'=>'Waan ka xumahay, looma oggola inaad taas sameyso.','Unknown provider.'=>'Bixiye aan la aqoon.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Geli cinwaanka adeegaga, tusaale ahaan http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Taasi uma eka furaha API. Nuqul ka yeeg mar kale, adiga oo aan wadata meelo bannaan.','Paste your API key first.'=>'Marka hore dheji furahaaga API.','Key removed.'=>'Furaha waa la saaray.','Models saved.'=>'Qaababka waa la keydiyay.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Geli magaca saxda ah ee moodalka, tusaale ahaan sida dukumentiyada bixiyuhu u qoreen.','Added %s. Choose it under "Which model to use".'=>'Waxaa lagu daray %s. Ka dooro hoosta "Waa maxay moodeelka la isticmaalayo".','Model removed.'=>'Qaabka waa la saaray.','Daily updates are off. The list that came with the plugin is used.'=>'Cusboonaysiinada maalinlaha ah waa damisanyihiin. Liiska la socda hordhacu (plugin) waa la isticmaalayaa.','Checked: %s.'=>'La hubiyay: %s.','Model lists refreshed.'=>'Liisaska moodalka waa la cusboonaysiiyay.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Furahaaga AI waxaa keydiyay nuqul ka cusub mid ka mid ah qalabkaaga dheeraadka ah (plugins). Cusboonaysii qalabkan, ama mar labaad geli furaha goobaha AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Furahaaga AI ee la keydiyay dib looma furan karo (furayaasha amniga ee boggu waa is beddeleen). Dib u geli dejinta AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI-gu wali lama habayn. Ku dar furaha bixiyaha AI dejinta AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Hawushan ma jiro nooc la doortay. Ka dooro mid ka mid ah dejinta AI.','That AI provider is not supported by this version of the plugin.'=>'Bixiyaha AI-gaas laguma taageero noocaan ah ee qalab-kordhiinta.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Goobtan ma gaari karto adeeggaaga AI. Hubi inuu shaqeynayo iyo in ciwaankiisa laga heli karo server-kaaga shabakadda (adeeg ka soocan kombuyuutarkaaga lagama heli karo goob la martigeliyay).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Boggan ma gaari karo %s. Hubi boggooda xaaladda; haddii ay shaqeynayaan, waxaa laga yaabaa in martigeliyahaagu xirayo xiriirada baxaya, ama ciwaanku waa khalad.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s waxay leedahay koontadaadu wax deyn ah ama saami ah oo hartay ma leh. Ku dar deyn ama kor u qaad xadkaaga koontadaada iyaga, ka dibna mar kale isku day.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s ma aysan aqbalin furahaaga. Waxaa laga yaabaa in si khaldan loo qoray, la baabi\'iyay ama uu dhacay. Abuur fure cusub oo ku dheji halkan.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s wuu diiday codsigan furahaaga. Furaha waxaa laga yaabaa inuusan heli karin qaabkan ama muuqaalkan, ama akoonkaaga ayaa u baahan in la xaqiijiyo.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model-ka "%1$s" waxaa laga heli karo %2$s furehaaga. Dooro model kale oo ku jira dejinta AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Qorshahaaga %2$s kuma jiro tusaalaha "%1$s". Dooro tusaale kale oo ku jira dejinta AI, ama ku cusboonaysii qorshahaaga iyaga.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s wuxuu xaddidayaa inta uu fureyhu si dhakhso ah u diri karo codsiyada. Sug daqiiqad oo dib u day, ama kor u qaad xadkaaga sicirka iyaga.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s waxay la kulmeysaa dhibaatooyin hadda (cillad ama culays xad-dhaaf ah dhinaceeda). Wax khaldan kama jiraan habayntaada. Dib u day dhowaan.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Codsiga AI wuu fashilmay sabab aanan garan karin. Isku day mar kale; haddii ay sii dhacdo, la xiriir taageerada oo u dir macluumaadka hoose.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Bixiyaha AI wuxuu ku jawaabay qaab uusan fiilankani akhrin karin. Mar kale isku day; haddii ay sii socoto, dooro qaab kale ama la xiriir taageerada.','Custom (OpenAI-compatible)'=>'Caadi ah (OpenAI-compatible)','Save a key for this provider first.'=>'Marka hore keydso furaha bixiyahan.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Furanahaagu wuu shaqaynayaa, laakiin bixiyuhu ma liis-gareeyay qaab qoraal ah (text model) oo loogu talagalay. Ku dar qaab adigu hoose.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Ku xidhan. %1$s wuxuu ku jawaabay iyadoo la adeegsanayo %2$s. Astaamahaaga AI waa diyaar in la isticmaalo.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Dooxada isticmaalahaaga laguma oggola inay isticmaasho AI goobtan. Weydii maamule.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Goobtan waxay gaartay xadka kharashka AI ee bishan. Maamulaha ayaa kordhin kara goobaha AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Boggan wuxuu gaadhay xadka uu bishii isticmaali jiray codsiyada AI. Maamulaha ayaa kordhin kara goobaha AI.','Usage and cost'=>'Isticmaalka iyo kharashka','The log, limits and role permissions apply to AI used through: %s.'=>'Diiwaanka, xadka iyo ogolaanshaha doorka waxaa lagu dabaqaa sirdoonka macmalka (AI) ee lagu isticmaalo iyada oo loo sii marayo: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Qiimaha waa kuwo qiyaas ah, oo laga soo saaray qiimaha la daabacay; qaab aan la aqoon qiimihiisa waxaa loo tirinayaa eber.','This month: %1$s requests, about %2$s.'=>'Bishan: %1$s codsiyo, ku dhawaad %2$s.','When'=>'Goortay','Who'=>'Kuma','Used for'=>'Loogu talagalay','Model'=>'Qaabka','Tokens in / out'=>'Calaamadaha soo / baxay','About'=>'Ku saabsan','Result'=>'Natiijo','No AI requests have been made yet.'=>'Weli lama samayn wax codsiyo AI ah.','Done'=>'La dhammeeyey','Limits and permissions'=>'Xadka iyo oggolaanshaha','Monthly spending limit (US dollars)'=>'Xadka kharashka bisha (US dollars)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'U daa madhan xad la\'aan. AI waxay istaagaysaa inta ka dhiman bisha marka kharashka qiyaasiga ahi uu gaaro heerkaas.','Monthly request limit'=>'Xadka codsiga bishii','Leave empty for no limit.'=>'U dhaaf faaruq xadka aan la koobnayn.','Who may use AI'=>'Ciddii isticmaali karta AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Calan ha saarin wax si aad ugu oggolaato qof kasta oo isticmaali kara sifooyinka furaha (plugin) inuu isticmaalo AI. Maamulayaashu waxay isticmaali karaan mar walba.','Save limits and permissions'=>'Kaydi xadka iyo ogolaanshaha','Limits and permissions saved.'=>'Xadka iyo fasaxyada waa la keydiyay.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Qoraalka maamulaha ee barnaamijkan ku dhex jira (script-yada) ayaa ka maqan nuqulkan. Fadlan dib ugu rakib xirmo rasmi ah.','This screen needs JavaScript.'=>'Shaarkani wuxuu u baahan yahay JavaScript.','Choose a language'=>'Dooro luuqad','Upgrade'=>'Codsii Kor U Qaadis','Pricing'=>'Qiimaha','Start Trial'=>'Bilow Tijaabada','Account'=>'Koontada','Contact Us'=>'Nala Xiriir','Affiliation'=>'Xubinimada','the kind of softwarePlugin'=>'Kudaraha','greetingHey %s,'=>'Hey %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Iska diwaangeli si aad u hesho ogeysiisyada iimeelka ee ku saabsan amniga & cusboonaysiinta sifooyinka, waxyaabaha waxbarashada, iyo dalabyada marmarka qaarkood, iyo inaad la wadaagto xoogaa xog ah oo aasaasi ah oo ku saabsan jawiga WordPress. Tani waxay naga caawin doontaa inaan %s ka dhigno mid ku habboon boggaaga oo ka sii wanaagsan qabashada waxa aad uga baahan tahay.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Ku biir si aad u hesho ogeysiisyo iimayl oo ku saabsan cusboonaysiinta amniga iyo astaamaha, waxyaabo waxbarasho, iyo dalabyo mararka qaar, oo aad la wadaagto macluumaad guud oo ku saabsan deegaanka WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Haddii aad ka gudubto arrintan, waa caadi! %1$s weli si fiican ayuu u shaqayn doonaa.','Allow & Continue'=>'Oggolow & Sii wad','verbSkip'=>'Ka bood','Skipping, please wait'=>'Waa la gudbayaa, fadlan sug','Continue'=>'Sii wad','Please wait'=>'Fadlan sug','as activating pluginActivating'=>'Waa la hawlgelinayaa','This will allow %s to'=>'Tani waxay oggolaan doontaa %s inuu','Privacy Policy'=>'Xeerka Khaaska ah','Terms of Service'=>'Shuruudaha Adeegga','License Agreement'=>'Heshiiska Sharciga ah','Have a license key?'=>'Ma haysataa furaha shatiga?','Activate License'=>'Firida Shatiga','View Basic Profile Info'=>'Arag macluumaadka guud ee xisaabtaada','Your WordPress user\'s: first & last name, and email address'=>'Magaca koowaad iyo kan dambe ee isticmaalahaaga WordPress, iyo cinwaanka iimaylka','View Basic Website Info'=>'Arag macluumaadka guud ee mareegta','Homepage URL & title, WP & PHP versions, and site language'=>'URL-ka bogga hoose & cinwaanka, noocyada WP & PHP, iyo luqadda bogga','View Basic %s Info'=>'Arag macluumaadka guud ee %s','Current %s & SDK versions, and if active or uninstalled'=>'Noocyada hadda ee %s iyo SDK, iyo haddii uu shaqaynayo ama laga saaray','Newsletter'=>'Wargeyska','Updates, announcements, marketing, no spam'=>'Cusboonaysiin, ogeysiis, suuq-geyn, spam ma jiro','View Diagnostic Info'=>'Eeg Xogta Baaritaanka','WordPress & PHP versions, site language & title'=>'Noocyada WordPress & PHP, luqadda & cinwaanka bogga','View Plugins & Themes List'=>'Eeg Liiska Qalabka & Mawduucyada','Names, slugs, versions, and if active or not'=>'Magacyada, gaaban (slugs), noocyada, iyo haddii ay shaqeynayaan iyo inkale','optional'=>'ikhtiyaari ah','Never miss an important update'=>'Weligi ha seegin wararka cusub ee muhiimka ah','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Waxaan soo bandhignay ikhtiyaarkan si aadan weligaba u seegin cusboonaysiin muhiim ah oo naga caawiso inaan ka dhigno %s mid si fiican ula jaanqaadaysa boggaaga isla markaana si wanaagsan u qabata waxa aad uga baahan tahay.','Thank you for updating to %1$s v%2$s!'=>'Mahadsan sanid in aad u cusbooneysiisay %1$s v%2$s!','That language is not one of this site\'s languages.'=>'Luqaddaasi ma aha mid ka mid ah luqadaha boggan.','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Horgalku waa inay noqotaa 1 ilaa 8 xaraf oo yar ama nambaro ah, ku billowda xaraf, mana aha inay magac ka dhigto qalabka la rakibo.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" ma aha koodh luqadeed. Isticmaal goobta WordPress ah sida fr_FR ama de_DE.','List at least one language.'=>'Liis garee ugu yaraan hal luqad.','That is more languages than one site can list.'=>'Taasi waa luqado ka badan inta uu hal bog liis gareyn karo.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Waxaa dhisay Neil Lock, oo ah madaxa fulinta ee Zinn Digital® Ltd','Version %s'=>'Nooca %s','Tranzly website'=>'Websaydhka Tranzly','Zinn Digital® website'=>'Zinn Digital® website','Settings saved.'=>'Dejinta waa la keydiyay.','See the Pro plans and pricing'=>'Fiiri qorshayaasha Pro iyo qiimaha','Languages'=>'Luqadaha','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Luqadda koowaad waa mida uu ku qoran yahay waxa ku jira. Booqdayaaluhu waxay ku beddelaan xannibaadda beddelaha luqadda.','(default)'=>'(caadi ah)','Locale code'=>'Koodka deegaanka','For example fr_FR'=>'Tusaale ahaan fr_FR','Name (optional)'=>'Magaca (ikhtiyaari)','For example Français'=>'Tusaale ahaan Français','Add language'=>'Ku dar luuqad','Front-end output'=>'Soosaarka hore','Class name prefix'=>'Horgalaha magaca fasalka','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Magac kasta oo fasal ah oo uu plugin-ku ku daabaco baxyadaada wuxuu ka bilaabmayaa horgalahan, si aynaan baxyadu u muujin plugin-kii dhisay. 1 ilaa 8 xaraf oo yaryar ama nambaro ah, oo ka bilaabmaya xaraf.','Beta updates'=>'Cusbooneysiinaha Beta','This site receives beta versions as updates.'=>'Boggani waxay heshaa noocyada beta-da ah casriyeyn ahaan.','This site receives stable versions only.'=>'Boggan waxa uu helaa oo keliya noocyada xasilloon.','Change this on the Account page'=>'Ka beddel tan bogagga Akoonka','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Noocyada Beta waxaa la siiyaa rakibaadaha Pro ee shatiga leh ee ku xiran akoonkooda. Marka la xiro, waxaad kala soo biiri kartaa bogga Akoonka.','Save settings'=>'Keydso dejinta','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Ku dar luqad labaad hoos yimaada Tranzly oo ku taal menu-ga maamulka, beddelaha ayaana halkan ka muuqan doona.','Switcher'=>'Beddelaha','Accessible label'=>'Calaamadda la heli karo','block titleLanguage switcher'=>'Beddelaha luqadda','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Xiriirinta boggan ee luqad kasta oo ka mid ah luqadaha mareegta. Ma soo bandhigto wax ilaa inta laba luqadood ama ka badan la liis gareeyo.','block keywordlanguage'=>'Luqadda','block keywordswitcher'=>'beddelaha','block keywordtranslation'=>'turjumid']];